-- New notification template: alerts every SUPER_ADMIN by email when the backend has been
-- deployed successfully. Intended to be sent from the last step of a deploy pipeline (or
-- manually via POST /api/v1/system/notify-deployment). Matches the V58/V59 premium chrome,
-- re-themed indigo for a deployment/ops alert instead of the green user-facing alerts.

INSERT INTO notification_templates (template, subject, message_body, is_email, is_sms, is_whatsapp) VALUES (
    'BACKEND-DEPLOYED',
    'Backend Deployed Successfully ({{environment}}) — PortfoliosBuilder',
    '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>PortfoliosBuilder</title><!--[if mso]><noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript><![endif]--><style>@media only screen and (max-width:600px){.email-container{width:100% !important}.email-body{padding:32px 22px !important}.email-header{padding:32px 24px 28px !important}}</style></head><body style="margin:0;padding:0;background-color:#eef1f6;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif"><div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">The backend just deployed successfully to {{environment}}.&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;&#8203;</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:44px 16px;background-color:#eef1f6"><tr><td align="center"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;margin:0 0 14px"><tr><td align="center"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="width:22px;height:22px;border-radius:7px;background-color:#4338ca;text-align:center;vertical-align:middle;font-size:11px;font-weight:800;color:#ffffff;line-height:22px">P</td><td style="padding-left:7px;color:#64748b;font-size:12px;font-weight:700;letter-spacing:0.04em">PORTFOLIOSBUILDER</td></tr></table></td></tr></table><table role="presentation" class="email-container" width="560" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:24px;overflow:hidden;box-shadow:0 1px 2px rgba(15,23,42,.04),0 28px 56px -16px rgba(15,23,42,.24);max-width:560px"><tr><td class="email-header" style="background-color:#4338ca;background-image:linear-gradient(135deg,#4f46e5,#4338ca);padding:38px 36px 32px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="vertical-align:middle"><p style="margin:0 0 4px;color:#c7d2fe;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:0.14em">DEPLOYMENT ALERT</p></td><td align="right" style="vertical-align:middle"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="width:52px;height:52px;border-radius:16px;background-color:rgba(255,255,255,0.14);text-align:center;vertical-align:middle"><table role="presentation" cellpadding="0" cellspacing="0" align="center" style="margin:0 auto"><tr><td style="width:38px;height:38px;border-radius:12px;background-color:rgba(255,255,255,0.24);text-align:center;vertical-align:middle;font-size:18px;line-height:38px">&#128640;</td></tr></table></td></tr></table></td></tr></table><h1 style="color:#ffffff;font-size:24px;margin:14px 0 0;font-weight:800;letter-spacing:-0.015em;line-height:1.3">Backend Deployed Successfully</h1><p style="color:#e0e7ff;font-size:14px;margin:8px 0 0;font-weight:500;line-height:1.5">A new build is live on {{environment}}.</p></td></tr><tr><td style="height:4px;background-color:#4f46e5;background-image:linear-gradient(90deg,#a5b4fc,#4f46e5,#4338ca);font-size:0;line-height:0">&nbsp;</td></tr><tr><td class="email-body" style="padding:38px 36px 8px"><p style="color:#374151;font-size:15px;margin:0 0 22px;line-height:1.6">Hi <strong>{{adminName}}</strong>,</p><p style="color:#374151;font-size:15px;margin:0 0 22px;line-height:1.6">The portfolio-be backend just finished deploying to <strong>{{environment}}</strong> and is up and responding to requests.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f9fafb;border-radius:14px;margin:0 0 20px"><tr><td style="padding:18px 20px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="padding:4px 0;color:#6b7280;font-size:13px;font-weight:600">Environment</td><td align="right" style="padding:4px 0;color:#111827;font-size:13px;font-weight:700">{{environment}}</td></tr><tr><td style="padding:4px 0;color:#6b7280;font-size:13px;font-weight:600">Version</td><td align="right" style="padding:4px 0;color:#111827;font-size:13px;font-weight:700">{{version}}</td></tr><tr><td style="padding:4px 0;color:#6b7280;font-size:13px;font-weight:600">Deployed at</td><td align="right" style="padding:4px 0;color:#111827;font-size:13px;font-weight:700">{{deployedAt}}</td></tr></table></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#eef2ff;border-left:4px solid #4f46e5;border-radius:0 14px 14px 0;margin:0 0 26px"><tr><td style="padding:18px 20px"><p style="color:#3730a3;font-size:13px;margin:0;line-height:1.6">No action needed unless something looks off — this is just a heads up that the deploy went through cleanly.</p></td></tr></table></td></tr><tr><td style="padding:0 36px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="border-top:1px solid #f1f5f9;font-size:0;line-height:0">&nbsp;</td></tr></table></td></tr><tr><td style="padding:22px 36px 30px;background-color:#fafbfc"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="width:18px;height:18px;border-radius:6px;background-color:#4338ca;text-align:center;vertical-align:middle;font-size:9px;font-weight:800;color:#ffffff;line-height:18px">P</td><td style="padding-left:7px;color:#94a3b8;font-size:11px;font-weight:800;letter-spacing:0.04em">PORTFOLIOSBUILDER</td></tr></table><p style="color:#9ca3af;font-size:12px;margin:10px 0 0;line-height:1.7">This is an automated message from PortfoliosBuilder.</p></td></tr></table></td></tr></table></body></html>',
    1, 0, 0
);

INSERT INTO notification_template_variables (variable_name, html_content, template_id)
SELECT 'adminName', '{{adminName}}', id FROM notification_templates WHERE template = 'BACKEND-DEPLOYED';
INSERT INTO notification_template_variables (variable_name, html_content, template_id)
SELECT 'environment', '{{environment}}', id FROM notification_templates WHERE template = 'BACKEND-DEPLOYED';
INSERT INTO notification_template_variables (variable_name, html_content, template_id)
SELECT 'version', '{{version}}', id FROM notification_templates WHERE template = 'BACKEND-DEPLOYED';
INSERT INTO notification_template_variables (variable_name, html_content, template_id)
SELECT 'deployedAt', '{{deployedAt}}', id FROM notification_templates WHERE template = 'BACKEND-DEPLOYED';
